class SolutionBagFingerprintTest {

	@Test
	void factorizedFingerprintSupportsAlgebraicCartesianProducts() {
		FactorizedSolutionBagFingerprint fingerprint = new FactorizedSolutionBagFingerprint(List.of("x", "y"));
		BindingSet x1 = row("x", Values.literal("x1"));
		BindingSet x2 = row("x", Values.literal("x2"));
		BindingSet y1 = row("y", Values.literal("y1"));
		BindingSet y2 = row("y", Values.literal("y2"));
		BindingSet y3 = row("y", Values.literal("y3"));

		FactorizedSolutionBagFingerprint.Summary left = fingerprint.union(
				fingerprint.factor(x1, List.of("x")), fingerprint.factor(x2, List.of("x")));
		FactorizedSolutionBagFingerprint.Summary right = fingerprint.union(
				fingerprint.union(fingerprint.factor(y1, List.of("y")), fingerprint.factor(y2, List.of("y"))),
				fingerprint.factor(y3, List.of("y")));
		FactorizedSolutionBagFingerprint.Fingerprint factorized = fingerprint
				.fingerprint(fingerprint.cartesianProduct(left, right));

		FactorizedSolutionBagFingerprint enumerated = new FactorizedSolutionBagFingerprint(List.of("x", "y"));
		for (BindingSet x : List.of(x1, x2)) {
			for (BindingSet y : List.of(y1, y2, y3)) {
				MapBindingSet product = new MapBindingSet(x.size() + y.size());
				x.forEach(product::addBinding);
				y.forEach(product::addBinding);
				enumerated.add(product);
			}
		}

		assertEquals(6L, factorized.rowCount());
		assertEquals(enumerated.fingerprint(), factorized);
	}

	@Test
	void factorizedFingerprintPreservesUnboundRowsAndDuplicateMultiplicity() {
		FactorizedSolutionBagFingerprint fingerprint = new FactorizedSolutionBagFingerprint(List.of("x", "y"));
		BindingSet x = row("x", Values.literal("x"));
		BindingSet unboundX = row();
		BindingSet y = row("y", Values.literal("y"));
		FactorizedSolutionBagFingerprint.Summary left = fingerprint.union(
				fingerprint.union(fingerprint.factor(x, List.of("x")), fingerprint.factor(x, List.of("x"))),
				fingerprint.factor(unboundX, List.of("x")));
		FactorizedSolutionBagFingerprint.Fingerprint factorized = fingerprint.fingerprint(
				fingerprint.cartesianProduct(left, fingerprint.factor(y, List.of("y"))));

		FactorizedSolutionBagFingerprint enumerated = new FactorizedSolutionBagFingerprint(List.of("x", "y"));
		enumerated.add(row("x", Values.literal("x"), "y", Values.literal("y")));
		enumerated.add(row("x", Values.literal("x"), "y", Values.literal("y")));
		enumerated.add(row("y", Values.literal("y")));

		assertEquals(3L, factorized.rowCount());
		assertEquals(enumerated.fingerprint(), factorized);
	}

	@Test
	void factorizedFingerprintRejectsExactCardinalityOverflow() {
		FactorizedSolutionBagFingerprint fingerprint = new FactorizedSolutionBagFingerprint(List.of("x"));
		FactorizedSolutionBagFingerprint.Summary maximum = new FactorizedSolutionBagFingerprint.Summary(
				Long.MAX_VALUE, new long[fingerprint.laneCount()]);
		FactorizedSolutionBagFingerprint.Summary twoRows = new FactorizedSolutionBagFingerprint.Summary(
				2L, new long[fingerprint.laneCount()]);

		assertThrows(ArithmeticException.class, () -> fingerprint.union(maximum, fingerprint.unitRow()));
		assertThrows(ArithmeticException.class, () -> fingerprint.cartesianProduct(maximum, twoRows));
		fingerprint.addSummary(maximum);
		assertThrows(ArithmeticException.class, () -> fingerprint.addSummary(fingerprint.unitRow()));
	}

	@Test
	void ignoresSolutionAndBindingIterationOrder() {
		BindingSet first = row("z", Values.iri("urn:z"), "a", Values.literal("alpha"));
		BindingSet firstReordered = row("a", Values.literal("alpha"), "z", Values.iri("urn:z"));
		BindingSet second = row("a", Values.literal("beta"));

		SolutionBagFingerprint.Fingerprint forward = fingerprint(List.of("z", "a"), first, second);
		SolutionBagFingerprint.Fingerprint reversed = fingerprint(List.of("a", "z"), second, firstReordered);

		assertEquals(forward, reversed);
	}

	@Test
	void countsDuplicateSolutionsWithTheirMultiplicity() {
		BindingSet first = row("value", Values.literal("first"));
		BindingSet duplicate = row("value", Values.literal("duplicate"));

		SolutionBagFingerprint.Fingerprint twoRows = fingerprint(List.of("value"), first, duplicate);
		SolutionBagFingerprint.Fingerprint threeRows = fingerprint(List.of("value"), first, duplicate, duplicate);

		assertEquals(2, twoRows.rowCount());
		assertEquals(3, threeRows.rowCount());
		assertNotEquals(twoRows.digestHex(), threeRows.digestHex());
	}

	@Test
	void distinguishesBindingNamesAndUnboundFromEmptyLiteral() {
		SolutionBagFingerprint.Fingerprint unbound = fingerprint(List.of("x"), row());
		SolutionBagFingerprint.Fingerprint emptyLiteral = fingerprint(List.of("x"),
				row("x", Values.literal("")));
		SolutionBagFingerprint.Fingerprint renamedBinding = fingerprint(List.of("y"),
				row("y", Values.literal("")));

		assertNotEquals(unbound.digestHex(), emptyLiteral.digestHex());
		assertNotEquals(emptyLiteral.digestHex(), renamedBinding.digestHex());
		assertNotEquals(unbound.digestHex(), renamedBinding.digestHex());
	}

	@Test
	void distinguishesRdfTermTypesAndLiteralMetadata() {
		Literal leftToRight = SimpleValueFactory.getInstance()
				.createLiteral("directional", "he", Literal.BaseDirection.LTR);
		Literal rightToLeft = SimpleValueFactory.getInstance()
				.createLiteral("directional", "he", Literal.BaseDirection.RTL);
		List<Value> distinctValues = List.of(
				Values.iri("urn:value"),
				SimpleValueFactory.getInstance().createBNode("urn:value"),
				Values.literal("urn:value"),
				Values.literal("1", XSD.STRING),
				Values.literal("1", XSD.INTEGER),
				Values.literal("one", "en"),
				Values.literal("one", "fr"),
				leftToRight,
				rightToLeft);
		Set<String> fingerprints = new HashSet<>();
		for (Value value : distinctValues) {
			fingerprints.add(fingerprint(List.of("value"), row("value", value)).digestHex());
		}

		assertEquals(distinctValues.size(), fingerprints.size());
	}

	@Test
	void recursivelyDistinguishesNestedRdfStarTriples() {
		TripleTerm innerOne = Values.tripleTerm(Values.iri("urn:subject"), Values.iri("urn:predicate"),
				Values.literal("one"));
		TripleTerm innerTwo = Values.tripleTerm(Values.iri("urn:subject"), Values.iri("urn:predicate"),
				Values.literal("two"));
		TripleTerm outerOne = Values.tripleTerm(Values.iri("urn:outer"), Values.iri("urn:contains"), innerOne);
		TripleTerm outerTwo = Values.tripleTerm(Values.iri("urn:outer"), Values.iri("urn:contains"), innerTwo);

		assertNotEquals(
				fingerprint(List.of("value"), row("value", outerOne)).digestHex(),
				fingerprint(List.of("value"), row("value", outerTwo)).digestHex());
	}

	@Test
	void versionsFingerprintAndIncludesSchemaForEmptyBags() {
		SolutionBagFingerprint.Fingerprint first = fingerprint(List.of("x"));
		SolutionBagFingerprint.Fingerprint second = fingerprint(List.of("y"));

		assertEquals(SolutionBagFingerprint.ALGORITHM_VERSION, first.algorithmVersion());
		assertEquals(0, first.rowCount());
		assertTrue(first.digestHex().matches("[0-9a-f]{64}"));
		assertNotEquals(first.digestHex(), second.digestHex());
	}

	@Test
	void snapshotIsRepeatableAndDoesNotFinishTheAccumulator() {
		SolutionBagFingerprint accumulator = new SolutionBagFingerprint(List.of("value"));
		accumulator.add(row("value", Values.literal("first")));
		SolutionBagFingerprint.Fingerprint first = accumulator.fingerprint();

		assertEquals(first, accumulator.fingerprint());
		accumulator.add(row("value", Values.literal("second")));
		assertNotEquals(first, accumulator.fingerprint());
	}

	@Test
	void rejectsAmbiguousSchemasAndUndeclaredBindings() {
		assertThrows(IllegalArgumentException.class, () -> new SolutionBagFingerprint(List.of("x", "x")));

		SolutionBagFingerprint accumulator = new SolutionBagFingerprint(List.of("x"));
		assertThrows(IllegalArgumentException.class,
				() -> accumulator.add(row("undeclared", Values.literal("value"))));
	}

	private static SolutionBagFingerprint.Fingerprint fingerprint(List<String> bindingNames, BindingSet... rows) {
		SolutionBagFingerprint accumulator = new SolutionBagFingerprint(bindingNames);
		for (BindingSet row : rows) {
			accumulator.add(row);
		}
		return accumulator.fingerprint();
	}

	private static MapBindingSet row(Object... nameValuePairs) {
		MapBindingSet row = new MapBindingSet(nameValuePairs.length / 2);
		for (int i = 0; i < nameValuePairs.length; i += 2) {
			row.addBinding((String) nameValuePairs[i], (Value) nameValuePairs[i + 1]);
		}
		return row;
	}
}
